use std::fmt::Write;

use chrono::NaiveDate;

use crate::model::{Kind, Priority, Project};

/// First line of every generated file; `export --out` only overwrites files
/// that start with it.
pub const MARKER: &str = "<!-- generated by ptrack; edit the registry, not this file -->";

fn cell(s: &str) -> String {
    s.replace('|', "\\|").replace('\n', " ")
}

/// Markdown view: upcoming deadlines, then one table per kind sorted by
/// priority, status and id.
pub fn markdown(projects: &[&Project], today: NaiveDate, horizon_days: i64) -> String {
    let mut out = String::new();
    let _ = writeln!(out, "{}\n", MARKER);
    let _ = writeln!(out, "# Projects\n\nGenerated {} from the ptrack registry ({} projects).\n", today, projects.len());

    let limit = today + chrono::Duration::days(horizon_days);
    let mut dues: Vec<_> = projects
        .iter()
        .flat_map(|p| p.deadlines.iter().map(move |d| (d, *p)))
        .filter(|(d, _)| d.date <= limit)
        .collect();
    if !dues.is_empty() {
        dues.sort_by_key(|(d, p)| (d.date, p.id.clone()));
        let _ = writeln!(out, "## Deadlines (next {} days and overdue)\n", horizon_days);
        let _ = writeln!(out, "| Date | In | ID | Slug | What |\n|---|---|---|---|---|");
        for (d, p) in dues {
            let n = (d.date - today).num_days();
            let when = if n < 0 { format!("**overdue {}d**", -n) } else { format!("{}d", n) };
            let _ = writeln!(out, "| {} | {} | {} | {} | {} |", d.date, when, p.id, p.slug, cell(&d.what));
        }
        out.push('\n');
    }

    for kind in Kind::ALL {
        let mut rows: Vec<&&Project> = projects.iter().filter(|p| p.kind == *kind).collect();
        if rows.is_empty() {
            continue;
        }
        rows.sort_by_key(|p| (p.priority.unwrap_or(Priority::Normal), p.status, p.id.clone()));
        let _ = writeln!(out, "## {} ({})\n", kind, rows.len());
        let _ = writeln!(out, "| ID | Slug | Title | Status | Pri | Venue | Next |\n|---|---|---|---|---|---|---|");
        for p in rows {
            let _ = writeln!(
                out,
                "| {} | {} | {} | {} | {} | {} | {} |",
                p.id,
                p.slug,
                cell(&p.title),
                p.status,
                p.priority.map(|x| x.to_string()).unwrap_or_default(),
                cell(p.venue.as_deref().unwrap_or("")),
                cell(p.next_action.as_deref().unwrap_or("")),
            );
        }
        out.push('\n');
    }
    out
}
